t=df['t'].values;A=df['A'].values;y=df['dA_dt'].values
V=np.var(y)
rng=np.random.default_rng(1)
def E(x): return np.exp(np.clip(x,-50,50))
models={
 'F1': (lambda p: -E(p[0]+p[1]*t+p[2]/t)*A**p[3] + E(p[4]+p[5]*t)*A**p[6] + p[7]+p[8]*t, 9),
 'F3': (lambda p: (p[0]+p[1]*t)*(A**p[2]-p[3])/(1+p[4]*A) + p[5]/t, 6),
 'F4': (lambda p: -(p[0]+p[1]/t+p[2]*t)*A**p[3]/(1+p[4]*A**p[5]) + p[6]*t**2 + p[7], 8),
 'F6': (lambda p: -(p[0]+p[1]/t+p[2]*t**2)*(1-E(-p[3]*A**p[4])) + (p[5]+p[6]*t)*A, 7),
}
out=[]
for name,(f,k) in models.items():
    best=(1e9,None)
    for s in range(30):
        p0=rng.normal(0,1,k)
        try:
            r=least_squares(lambda p: np.nan_to_num(f(p)-y,nan=1e6,posinf=1e6,neginf=-1e6), p0, max_nfev=1500)
            mse=np.mean(r.fun**2)/V
            if mse<best[0]: best=(mse,r.x)
        except Exception as e:
            pass
    out.append(f"{name} {best[0]:.6g} {np.round(best[1],3)}")
